-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.paladin.holy.Name"] = "Свет"
L["rm.era.paladin.holy.Description"] = "Лечение в группе для ветки «Свет» с 10 уровня. Действует на вашу дружественную цель и выбирает исцеление по недостающему здоровью: Очищение, Шок небес в движении, Свет небес высшего ранга ниже 40%, Свет небес 6-го ранга ниже 65%, Вспышка Света высшего ранга ниже 85%, Вспышка Света 4-го ранга ниже 95%. С врагом в зоне ближнего боя: Печать мудрости и, вне рейдов, Правосудие. Напоминания: Аура сосредоточенности или Аура благочестия, Благословение мудрости, Божественное одобрение и Возложение рук для цели при смерти. Кого лечить, выбираете вы; паладин ветки «Свет», играющий в одиночку, получает встроенную ротацию «Воздаяние»."
L["rm.era.paladin.protection.Name"] = "Защита"
L["rm.era.paladin.protection.Description"] = "Танкование с 1 по 60 уровень; выбирается по Праведному неистовству или ветке «Защита». Печать праведности (Печать мудрости, когда мана падает ниже 40%), Щит небес и Правосудие для начала боя, Щит небес постоянно поддерживается, Освящение и Гнев небес (нежить и демоны), когда с вами сражаются два и более врага, иначе один раз Правосудие воина света, затем Правосудие и Освящение при лишней мане, Экзорцизм против нежити и демонов. Напоминания: Праведное неистовство, Аура благочестия, Благословение неприкосновенности, королей или могущества, Возложение рук, когда вы почти мертвы. Провокации, частое применение Благословения королей и ранги заклинаний остаются за вами."
L["rm.era.paladin.protection.icyveins.Name"] = "Защита, Печать мудрости (Icy Veins)"
L["rm.era.paladin.protection.icyveins.Description"] = "Рейдовое танкование по Icy Veins с ротацией мудрости от Wowhead — альтернатива рекомендуемой встроенной ротации «Защита», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Поддерживает Печать мудрости и применяет её Правосудие всякий раз, когда на цели нет Правосудия мудрости, иначе Правосудие только для начала боя; Щит небес, Освящение по каждой готовности, Гнев небес против групп нежити и демонов, Экзорцизм и Великое благословение королей как заполнитель для угрозы в рейде. Те же напоминания, что и в рекомендуемой встроенной ротации."
L["rm.era.paladin.retribution.Name"] = "Воздаяние"
L["rm.era.paladin.retribution.Description"] = "Воздаяние в ближнем бою с 1 по 60 уровень; также ротация по умолчанию для любого паладина, которому не подходит другая встроенная ротация. Против элитных противников и в долгих боях вне рейдов ставит Печать воина Света и один раз применяет её Правосудие; иначе поддерживает печать (Печать повиновения при оружии со скоростью 3,5 секунды или медленнее, иначе Печать праведности), Экзорцизм и Гнев небес против нежити и демонов, Молот гнева, Правосудие по готовности, Освящение, пока действует Отмщение, или против двух и более врагов рядом. Напоминания: Аура святости, Аура воздаяния или Аура благочестия, Благословение мудрости в одиночной игре или Благословение могущества в группе, исцеление между боями, Божественный щит, Божественная защита или Возложение рук, когда вы вот-вот умрёте. Твист печатей — отдельная встроенная ротация; выбор цели и позиционирование остаются за вами."
L["rm.era.paladin.retribution.twist.Name"] = "Воздаяние, твист печатей"
L["rm.era.paladin.retribution.twist.Description"] = "По умолчанию выключена; включите её, если вы твистите печати. Для паладина ветки «Воздаяние» с Печатью повиновения: поддерживает Печать праведности, в последние 0,4 секунды перед ударом оружием переключается на Печать повиновения 1-го ранга и обратно, Правосудие по готовности, Экзорцизм и Гнев небес против нежити и демонов, Молот гнева, Освящение при Отмщении. Требует много маны и точного расчёта времени. Те же напоминания, что и во встроенной ротации «Воздаяние»."
L["rm.forever.paladin.holy.Name"] = "Свет"
L["rm.forever.paladin.holy.Description"] = "Групповое лечение, когда «Свет» — ваша основная ветка талантов с 21 очком (уровень Шока небес), пока Праведное неистовство выключено (сюда же попадает «шокадин» в группе). Лечит вашу текущую дружественную цель: Шок небес по цели с вашим Дозором Света, Дозор Света в бою, Очищение или Омовение, Шок небес в движении, Свет небес с Приливом Света, Вспышка Света как основное лечение. Против врага: Правосудие света при наложенной Печати Света, Шок небес, Дозор Света, Священный удар, Экзорцизм. Напоминания: Печать Света, если печати нет, Божественное одобрение в бою на дружественную цель, ваша аура и благословение. В Forever здоровье и мана скрыты от аддонов, поэтому единственный признак того, кого нужно лечить, — выбранная вами цель; экстренные Шоки небес, мощный Свет небес и Возложение рук остаются за вами."
L["rm.forever.paladin.holy.wowhead.Name"] = "Свет, Шок небес по готовности (Wowhead)"
L["rm.forever.paladin.holy.wowhead.Description"] = "Стиль лечения Wowhead — альтернатива рекомендуемой встроенной ротации «Свет», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Шок небес как обычное лечение по готовности, рассеивание, Вспышка Света (в Forever здоровье скрыто, поэтому Свет небес при большой нехватке здоровья — на ваше усмотрение). Против врага поддерживает ваше Правосудие света: переключается на Печать Света, применяет Правосудие и возвращается к Печати праведности, затем Священный удар, Экзорцизм против нежити и демонов, Шок небес и Освящение. Те же напоминания, что и во встроенной ротации «Свет»."
L["rm.forever.paladin.protection.Name"] = "Защита (Wowhead)"
L["rm.forever.paladin.protection.Description"] = "Танкование, когда «Защита» — ваша основная ветка талантов или вы включаете Праведное неистовство. Когда цель сражается с кем-то другим: Правосудие с Печатью ярости (провокация), Стремительное правосудие, чтобы сбросить его восстановление. Если в бою два и более врага: Освящение, Экзорцизм и Гнев небес против нежити и демонов, Священный удар. Против одного врага: Экзорцизм против нежити и демонов, Священный удар, Освящение. Напоминания: Праведное неистовство, Печать ярости, Правосудие по готовности, Щит небес во время танкования, ваша аура и благословение. В Forever здоровье и мана скрыты от аддонов, поэтому Щит храмовника и Возложение рук остаются за вами. Пулл, позиционирование и прочие провокации остаются за вами."
L["rm.forever.paladin.protection.icyveins.Name"] = "Защита, сначала Освящение (Icy Veins)"
L["rm.forever.paladin.protection.icyveins.Description"] = "Стиль танкования Icy Veins — альтернатива рекомендуемой встроенной ротации «Защита» от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Освящение в первую очередь всякий раз, когда хватает маны, в том числе против одного врага; Правосудие приберегается для провокации (без напоминания «по готовности»), а Стремительное правосудие сбрасывает его восстановление; затем Священный удар и Экзорцизм против нежити и демонов. В остальном — те же напоминания для танка."
L["rm.forever.paladin.retribution.Name"] = "Воздаяние"
L["rm.forever.paladin.retribution.Description"] = "Воздаяние и любой паладин ближнего боя с 1 по 60 уровень; также ротация паладина по умолчанию в Forever. Поддерживает печать для урона и обновляет её, только когда она подходит к концу: Печать воина Света, по которой один раз применяется Правосудие на элитной цели, затем Печать повиновения с медленным оружием (3,0 с), иначе Печать праведности. Затем Священный удар по готовности, Шок небес и Дозор Света для «шокадина», Экзорцизм против нежити и демонов, Освящение при трёх и более врагах, Молот гнева, когда его можно применить, и ближний бой. Правосудие не задействует общее время восстановления, поэтому о нём напоминается всякий раз, когда наложена печать. Прочие напоминания: ваша аура и благословение (Аура воздаяния и Благословение королей, как только изучены; выбранные вами сохраняются). Необязательный шаг, по умолчанию выключенный: Молот правосудия перед Правосудием с Печатью повиновения. В Forever мана, здоровье и таймер удара скрыты от аддонов, поэтому экономия маны, лечение себя, Возложение рук и смена печатей с Искажённым светом остаются за вами. Составлено по руководствам бета-версии для 30 уровня."
L["rm.mop.paladin.holy.Name"] = "Рекомендуемая"
L["rm.mop.paladin.holy.Description"] = "Для «Света» с 10 уровня при специализации «Свет». С союзником в цели лечит: при 3 ед. Священной силы (или Божественном замысле) Свет зари, когда ранены трое рядом с вами, иначе Вечное пламя на цель без него, иначе Торжество; Шок небес по готовности; Прилив Света — в Святое сияние или Божественный свет, три наложения Самоотверженного целителя — в Святое сияние или Вспышку Света; Вспышка Света ниже 35%; Святое сияние для раненой группы; Божественный свет, затем Свет небес для восполнения. С врагом в цели наносит урон: Шок небес, Правосудие, Удар воина Света, Божественная призма, Смертный приговор, Молот гнева, Обличение. Напоминания: Печать прозрения, если активна другая печать (кроме Печати праведности) или никакая, благословения, Укор, Частица Света и Священный щит на ваш фокус (сделайте танка фокусом), Святая клятва при мане ниже 60%, Молот Света и ваши способности исцеления с восстановлением, когда у троих меньше 70% здоровья, Возложение рук на умирающую цель. Кого лечить, рассеивание и лечение по наведению мыши остаются за вами."
L["rm.mop.paladin.protection.Name"] = "Рекомендуемая"
L["rm.mop.paladin.protection.Description"] = "Рекомендуется для «Защиты» с 10 уровня при специализации «Защита». Начинает бой Щитом мстителя, затем Щит мстителя при срабатывании Великого воина Света, Щит мстителя, Молот гнева, Удар воина Света, Правосудие, ваш талант 90 уровня, Освящение, Гнев небес и Священный щит. Когда с вами сражаются три и более врага, переходит на Щит мстителя, Освящение, Молот праведника, Правосудие и Гнев небес. Щит праведника, Вечное пламя и Торжество не затрагивают общее время восстановления, поэтому подсвечиваются рядом с ротацией: Щит праведника всякий раз, когда вы можете его себе позволить, Вечное пламя на себя, когда оно заканчивается, при 3 ед. Священной силы и трёх наложениях Бастиона славы, Торжество при здоровье ниже половины без этого таланта. Другие напоминания: Праведное неистовство, Печать прозрения, если активна другая печать (кроме Печати праведности) или никакая, благословения, Укор, Священный щит, Гнев карателя и Святой каратель, пока вы танкуете, а также Защитник древних королей, Ревностный защитник, Божественная защита и Возложение рук в зависимости от вашего здоровья. Ротация не видит входящий урон, поэтому крупные защитные способности планируйте сами."
L["rm.mop.paladin.protection.simulator.Name"] = "Накопление Священной силы (симулятор)"
L["rm.mop.paladin.protection.simulator.Description"] = "Альтернатива рекомендуемой встроенной ротации «Защита», по умолчанию выключена: включите её и выключите ту или повысьте её приоритет. Следует спискам танкования симулятора: Щит праведника ждёт полной Священной силы, если только ваше здоровье не упадёт ниже 40% или Божественный замысел не сделает его бесплатным; Вечное пламя незадолго до того, как оно спадёт, при более чем двух наложениях Бастиона славы; Священный щит постоянно поддерживается; Святой каратель и Гнев карателя по готовности. Приёмы набора идут так: Удар воина Света, Правосудие, затем Щит мстителя, Гнев небес, талант 90 уровня и Молот гнева, с тем же порядком AoE против трёх врагов. Защитные способности под механики босса — за вами."
L["rm.mop.paladin.retribution.Name"] = "Рекомендуемая"
L["rm.mop.paladin.retribution.Description"] = "Рекомендуется для «Воздаяния» с 10 уровня при специализации «Воздаяние». Поддерживает Дознание (применяется при 3 ед. Священной силы, обновляется в последние 3 секунды; с 81 уровня), тратит Вердикт храмовника при полной Священной силе или при бесплатном срабатывании, прежде чем набирать её дальше, затем Молот гнева, Удар воина Света, Правосудие и Экзорцизм, а Вердикт храмовника при 3 ед., когда больше ничего не готово. Во время Гнева карателя тратит сразу и ставит Правосудие перед Ударом воина Света. Когда с вами сражаются два и более врага, переходит на Божественную бурю, а при четырёх рядом добавляет Молот праведника. Начинает бой с дистанции Правосудием или Экзорцизмом и предлагает Торжество, когда вы в одиночку и в опасности. Напоминания: Печать правды, если активна другая печать или никакая (Печать праведности сохраняется), Благословение королей или могущества, Укор, Гнев карателя и Защитник древних королей при действующем Дознании против элитных противников, Святой каратель во время Гнева карателя, Смертный приговор и Молот Света, а также Божественная защита и Возложение рук при низком здоровье. Печать праведности против групп и выбор символов остаются за вами."
L["rm.mop.paladin.retribution.warcrafttavern.Name"] = "Сначала Экзорцизм (Warcraft Tavern)"
L["rm.mop.paladin.retribution.warcrafttavern.Description"] = "Альтернатива рекомендуемой встроенной ротации «Воздаяние», по умолчанию выключена: включите её и выключите ту или повысьте её приоритет. Первым идёт Экзорцизм по каждой готовности и при каждом сбросе от Искусства войны; Дознание применяется при любой Священной силе, когда его нет, и обновляется при 3 ед. в последние 20 секунд; затем Удар воина Света, Правосудие, Вердикт храмовника и Молот гнева (первым во время Гнева карателя со Священным гневом). Против двух и более врагов — Удар воина Света, Молот Света, Правосудие, Божественная буря и Молот гнева. Гнев карателя и Защитник древних королей предлагаются только против элитных противников. Печать праведности, которую руководство советует при любом бое с несколькими целями рядом, остаётся за вами."
L["rm.mop.paladin.unspecialized.Name"] = "До выбора специализации"
L["rm.mop.paladin.unspecialized.Description"] = "Для уровней 1–9 и любого паладина, который ещё не выбрал специализацию; встроенная ротация специализации вступает в силу, как только вы её выберете. Начинает бой с дистанции Правосудием, затем Удар воина Света и Правосудие, с Молотом правосудия, когда вы в одиночку и у вас меньше половины здоровья, и Торжеством ниже 40%. Напоминания: Печать повиновения (с 24 уровня — Печать правды), если вы не в ней, Благословение королей, Укор и Вспышка Света вне боя, когда вы ранены."
L["rm.retail.paladin.holy.Name"] = "Icy Veins"
L["rm.retail.paladin.holy.Description"] = "«Свет» в Midnight, для справки: Rotation Master выбирает заклинание, а не цель, а игра скрывает здоровье всех в бою, поэтому эта ротация поддерживает оборот вашей энергии Света и способностей с восстановлением на любой выбранной вами цели, а решать, кому нужно лечение, оставляет вам. Энергия Света остаётся видимой в бою, поэтому сначала она тратится при 5 ед., а после других исцелений — при 3 и более. С дружественной целью: Вечное пламя или Торжество при 5 ед. энергии Света, Вспышка Света при Приливе Света, Шок небес, Вечное пламя или Торжество при 3 и более ед., Свет небес, Вспышка Света; Свет зари остаётся за вами. С враждебной целью: Щит праведника при 5 ед. энергии Света, Шок небес, Щит праведника при 3 и более ед., Правосудие, Удар воина Света, Освящение. Напоминания в бою: Божественный благовест, Божественная призма, Святой оплот или Святое оружие, Частица добродетели на дружественную цель, Божественная защита; аура между боями; Укор. Возложение рук остаётся за вами. Гнев карателя и Владение аурами остаются за вами."
L["rm.retail.paladin.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.paladin.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию паладина). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций паладина, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.paladin.protection.Name"] = "Боевой помощник Blizzard"
L["rm.retail.paladin.protection.Description"] = "Рекомендуется для специализации «Защита» в Midnight. Показывает предложение Боевого помощника Blizzard, которое уже включает Щит праведника, Гнев карателя и Часового, и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: аура между боями, Укор против прерываемого заклинания, а также Ревностный защитник и Защитник древних королей по готовности в бою. Здоровье на Retail скрыто, поэтому момент для их применения и для Возложения рук — на ваше усмотрение. Провокации и позиционирование остаются за вами."
L["rm.retail.paladin.protection.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.paladin.protection.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядку Icy Veins и SimulationCraft нужны положительные эффекты Освящения, Авангарда и Яркого Света, которые Midnight скрывает в бою. Освящение перед боем; затем Божественный благовест, Молот Света, Освящение, если вы не стоите в нём, Щит мстителя с Авангардом, Щит праведника при 3 и более ед. энергии Света, Молот гнева, Правосудие, Благословенный молот или Молот праведника, Щит мстителя, Торжество с Ярким Светом, Освящение. Напоминания: Гнев карателя или Часовой, Святой оплот, Святое оружие вне Гнева карателя, защитные способности, аура, Укор."
L["rm.retail.paladin.protection.wowhead.Name"] = "Освящение как заполнитель, для справки (Wowhead)"
L["rm.retail.paladin.protection.wowhead.Description"] = "Только для справки, по умолчанию выключена: порядок танкования по Wowhead. Правосудие по готовности, Щит праведника, Щит мстителя, Божественный благовест при 0 ед. энергии Света, Благословенный молот или Молот праведника, а Освящение — только как заполнитель. Здоровье на Retail скрыто, поэтому Торжество при здоровье ниже половины остаётся за вами. Те же напоминания, что и в справочной ротации Icy Veins."
L["rm.retail.paladin.retribution.Name"] = "Боевой помощник Blizzard"
L["rm.retail.paladin.retribution.Description"] = "Рекомендуется для специализации «Воздаяние» в Midnight. В бою игра теперь скрывает от аддонов положительные и отрицательные эффекты, время восстановления и здоровье, поэтому эта ротация показывает на ваших панелях команд собственное предложение Боевого помощника Blizzard (ротация одной кнопкой) и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, чего это предложение никогда не охватывает: аура между боями, Укор против прерываемого заклинания и Божественная защита по готовности в бою. Здоровье на Retail скрыто, поэтому момент для Божественной защиты и Возложения рук — на ваше усмотрение. Аксессуары и расовые способности остаются за вами."
L["rm.retail.paladin.retribution.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.paladin.retribution.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Icy Veins и SimulationCraft читает положительные эффекты, заряды и число врагов, которые Midnight скрывает в бою, поэтому ротация не может там надёжно работать. Молот Света; бесплатный расходующий приём при Божественном замысле; при 5 ед. энергии Света, пока Испепеляющий след восстанавливается, — расходующий приём; Испепеляющий след; Божественный благовест; Клинок справедливости при Искусстве войны; Молот гнева до переполнения зарядов; при 3 и более ед. энергии Света — Божественная буря против двух и более врагов (или при Небесной мощи), иначе Окончательный приговор; Молот гнева; Клинок справедливости; Правосудие; Удары храмовника или Удар воина Света. Энергия Света остаётся видимой в бою, поэтому пороги её траты там работают. Напоминания: Гнев карателя, Смертный приговор при готовом Испепеляющем следе, аура, Укор, защитные способности."
L["rm.sod.paladin.holy.Name"] = "Свет (SoD)"
L["rm.sod.paladin.holy.Description"] = "Лечение в группе для сезона открытий; выбирается по выгравированной Частице Света, Божественному свету или Священному щиту либо по ветке «Свет» без Удара воина Света. Действует на вашу дружественную цель: Очищение, Шок небес в движении или ниже 30%, Божественный свет (Свет небес, когда маны меньше половины) ниже 60%, Вспышка Света ниже 90%. С врагом в зоне ближнего боя только поддерживает печать. Напоминания: Частица Света и Священный щит на цель, у которой их нет, Аура сосредоточенности или Аура благочестия, Благословение мудрости, Божественное одобрение и Возложение рук для цели при смерти. Руководства, на которых она основана, относятся к 4-й фазе; кого лечить, выбираете вы."
L["rm.sod.paladin.holy.wowhead.Name"] = "Свет, сначала Свет небес (SoD, Wowhead)"
L["rm.sod.paladin.holy.wowhead.Description"] = "Порядок лечения 4-й фазы по Wowhead для снаряжения с упором на критический эффект — альтернатива рекомендуемой встроенной ротации «Свет» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Божественный свет или Свет небес ниже 75%, затем Очищение, Шок небес при небольшой нехватке здоровья или в движении, Вспышка Света ниже 95%. Те же напоминания, что и в рекомендуемой встроенной ротации."
L["rm.sod.paladin.protection.Name"] = "Защита (SoD)"
L["rm.sod.paladin.protection.Description"] = "Танкование для сезона открытий; выбирается по Праведному неистовству, выгравированному Молоту праведника или Щиту праведности либо по ветке «Защита». Печать мученичества, начало боя Щитом небес, Щитом мстителя и Экзорцизмом, Щит небес постоянно поддерживается; против одной цели — Молот праведника, Щит праведности, Экзорцизм, Щит мстителя, Правосудие, Божественная буря, Освящение; когда с вами сражаются три и более врага — Молот праведника, Щит мстителя, Освящение, Щит праведности, Экзорцизм. Напоминания: Праведное неистовство, Щит небес перед боем, Аура благочестия, Благословение неприкосновенности или королей, Гнев карателя, Божественная защита ниже 40%, Возложение рук, Длань возмездия в группе, когда ваша цель атакует кого-то другого."
L["rm.sod.paladin.protection.simulator.Name"] = "Защита (SoD, симулятор)"
L["rm.sod.paladin.protection.simulator.Description"] = "Список танкования симулятор — альтернатива рекомендуемой встроенной ротации «Защита» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Правосудие всякий раз, когда действует печать, печать обновляется незадолго до истечения, Щит небес, Щит мстителя, Молот праведника, Экзорцизм, в последнюю очередь Щит праведности. Те же напоминания, что и в рекомендуемой встроенной ротации."
L["rm.sod.paladin.retribution.Name"] = "Воздаяние (SoD)"
L["rm.sod.paladin.retribution.Description"] = "Ближний бой для сезона открытий с 1 по 60 уровень; там же — ротация по умолчанию для любого паладина. Поддерживает Печать мученичества (Печать праведности, пока её нет), начинает бой Экзорцизмом, применяет Божественную бурю при трёх единицах Священной силы, затем по скорости оружия: с двуручным оружием скоростью 3,3 секунды или медленнее — Удар воина Света, Экзорцизм, Божественная буря и Правосудие; с более быстрым — Правосудие только по истечении печати, затем Экзорцизм, Удар воина Света и Божественная буря. Освящение при запасе маны или против трёх врагов рядом, Гнев небес против нежити и демонов (против любых целей, если выгравирована Очищающая сила), Молот гнева при запасе маны (всегда, если выгравирован Улучшенный молот гнева). Руны используются по мере того, как вы их гравируете. Напоминания: Аура святости, благословение, Гнев карателя вместе с Владением аурами, исцеление между боями, Божественный щит, когда вы вот-вот умрёте."
L["rm.sod.paladin.retribution.icyveins.Name"] = "Воздаяние (SoD, Icy Veins, 4-я фаза)"
L["rm.sod.paladin.retribution.icyveins.Description"] = "Более старый список 4-й фазы от Icy Veins и Warcraft Tavern, подходит и для прокачки; альтернатива рекомендуемой встроенной ротации «Воздаяние» для сезона открытий, по умолчанию выключена: включите её и выключите ту или повысьте её приоритет. Один раз Правосудие воина света против элитных противников и в долгих боях, Печать мученичества, Экзорцизм, Удар воина Света, Божественная буря и Правосудие по готовности, Освящение при запасе маны или против трёх врагов рядом, Молот гнева. Те же напоминания, что и в рекомендуемой ротации."
L["rm.sod.paladin.retribution.stacking.Name"] = "Воздаяние, наложение печатей (SoD)"
L["rm.sod.paladin.retribution.stacking.Description"] = "По умолчанию выключена; включите её с руной Души носителя печати или с комплектом из шести предметов, при котором печати задерживаются (Rotation Master не видит ни то, ни другое). Поддерживает одновременно Печать повиновения и Печать мученичества, Божественная буря при трёх единицах Священной силы, Удар воина Света, Экзорцизм, Гнев небес против нежити и демонов (против любых целей, если выгравирована Очищающая сила), Освящение и Правосудие, пока действуют обе печати."
L["rm.sod.paladin.retribution.twist.Name"] = "Воздаяние, твист печатей (SoD)"
L["rm.sod.paladin.retribution.twist.Description"] = "По умолчанию выключена; включите её, если вы твистите печати с медленным двуручным оружием. Переключается между Печатью мученичества и Печатью повиновения в последние 0,4 секунды перед каждым ударом оружием, ничего не предлагает на общем времени восстановления за 1,9 секунды до удара, применяет Правосудие, пока действуют обе печати, и использует по одному заполнителю на удар: Божественная буря при трёх единицах Священной силы, Удар воина Света, Экзорцизм. Нужны таймер ударов оружием и практика."
L["rm.sod.paladin.shockadin.Name"] = "Шокадин (SoD, симулятор)"
L["rm.sod.paladin.shockadin.Description"] = "По умолчанию выключена; включите её, если наносите урон с веткой «Свет». Применяется, когда «Свет» — ваша основная ветка, а выгравирован Шок и трепет. Печать мученичества (иначе Печать праведности), её Правосудие по истечении, Шок небес для поддержания Солнечного света или при трёх единицах Священной силы, Экзорцизм и Удар воина Света. Те же напоминания, что и в рекомендуемой встроенной ротации «Воздаяние» для сезона открытий."
L["rm.tbc.paladin.holy.Name"] = "Свет (Icy Veins и Wowhead)"
L["rm.tbc.paladin.holy.Description"] = "Лечение для паладина ветки «Свет» в группе, на дружественной цели: Возложение рук или Шок небес для умирающей цели, Очищение (до 42 уровня — Очистить), Шок небес в движении, Свет небес при сильном уроне, Свет небес 5-го ранга для поддержания Благоволения Света, в остальных случаях Вспышка Света. С враждебной целью поддерживает Правосудие мудрости. Напоминания: Аура сосредоточенности, Благословение мудрости, Божественное просветление и Божественное одобрение. Паладин ветки «Свет», играющий в одиночку, получает вместо этого встроенную ротацию «Воздаяние»."
L["rm.tbc.paladin.holy.wowhead.Name"] = "Свет (лечение танков, Wowhead)"
L["rm.tbc.paladin.holy.wowhead.Description"] = "Лечение танков в рейде по Wowhead — альтернатива рекомендуемой встроенной ротации «Свет», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Свет небес, как только цели не хватает десятой части здоровья, Вспышка Света — только при небольшой нехватке, с теми же экстренными мерами, очищением, Правосудием и напоминаниями, что и в смешанной встроенной ротации «Свет»."
L["rm.tbc.paladin.protection.icyveins.Name"] = "Защита (Icy Veins)"
L["rm.tbc.paladin.protection.icyveins.Description"] = "«Танкование» по Icy Veins — альтернатива рекомендуемой встроенной ротации «Защита» от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Правосудие воина Света, если его никто не поддерживает, Печать праведности (мудрости — против групп), Освящение как основной источник угрозы, Правосудие, Щит небес, затем Щит мстителя и Молот гнева по готовности. Те же напоминания, что и в варианте Wowhead, но без Гнева карателя."
L["rm.tbc.paladin.protection.wowhead.Name"] = "Защита (Wowhead и симулятор)"
L["rm.tbc.paladin.protection.wowhead.Description"] = "Танкование для ветки «Защита» или для любого паладина с включённым Праведным неистовством. Начинает бой со Щита небес, Щита мстителя и Правосудия; против цели с сокрушительными ударами (мировой босс или цель на три и более уровня выше вас) первым идёт Щит небес; затем Освящение, Экзорцизм против нежити и демонов, Правосудие, Щит небес, Гнев небес против групп нежити, Щит мстителя, кроме целей с сокрушительными ударами. Печать мудрости против групп при нехватке маны, иначе Печать праведности. Напоминания: Праведное неистовство, Аура благочестия, Благословение неприкосновенности (или королей, или мудрости), Гнев карателя, Возложение рук. Провокации и смена целей остаются за вами."
L["rm.tbc.paladin.retribution.icyveins.Name"] = "Воздаяние (Icy Veins)"
L["rm.tbc.paladin.retribution.icyveins.Description"] = "«Воздаяние» по Icy Veins — альтернатива рекомендуемой встроенной ротации «Воздаяние» от Wowhead, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Правосудие воина Света один раз на цель, Печать праведности (Печать повиновения — только с медленным оружием, Печать крови или мученика — как только изучена), Удар воина Света, Молот гнева и Правосудие по готовности, Освящение при двух и более врагах, Экзорцизм против нежити и демонов и Шок небес для паладинов, качающихся в ветке «Свет». Те же напоминания, что и в варианте Wowhead."
L["rm.tbc.paladin.retribution.twist.Name"] = "Воздаяние, твист печатей"
L["rm.tbc.paladin.retribution.twist.Description"] = "По умолчанию выключена; включите её, если вы твистите печати (с 64 уровня, Печать повиновения и Печать крови или мученика). Начинает бой с Правосудия воина Света, затем перед каждым ударом оружием заранее ставит Печать повиновения (ранг 1) и в последние 0,4 секунды переключается на Печать крови или мученика; Удар воина Света между твистами, Правосудие только с Печатью крови или мученика, Экзорцизм и Освящение лишь как заполнители, а при мане ниже 12% держит Печать крови без твиста. Нужен надёжный таймер ударов оружием; задержка не учитывается."
L["rm.tbc.paladin.retribution.wowhead.Name"] = "Воздаяние (Wowhead и симулятор)"
L["rm.tbc.paladin.retribution.wowhead.Description"] = "Воздаяние в ближнем бою с 1 по 70 уровень; также используется по умолчанию для любого паладина, которому не подходит другая встроенная ротация. Начинает бой с каждой целью с Правосудия мудрости (при нехватке маны) или Правосудия воина Света, поддерживает вашу лучшую печать (Печать крови или мученика, затем повиновения, затем праведности), Удар воина Света, Правосудие только с Печатью праведности, крови или мученика (или повиновения — по оглушённой цели), Экзорцизм против нежити и демонов, Освящение при трёх и более врагах, если маны с запасом. Молот гнева остаётся за вами (Wowhead применяет его только по убегающим целям). Напоминания: Аура святости, воздаяния или благочестия, благословение на себя, исцеление после боя, Гнев карателя. Твист печатей — отдельная встроенная ротация."
